#!/usr/bin/env php
<?php

/**
 * Analyze OpenAPI Test Results
 *
 * Analyzes the JSON files generated by test_all_openapi_endpoints.php
 * and creates a structured analysis report
 *
 * Usage: php analyze_test_results.php
 */

error_reporting(E_ALL);
ini_set('display_errors', '1');

$resultsDir = __DIR__ . '/openapi_test_results';
$analysisFile = $resultsDir . '/_analysis_report.json';

if (!is_dir($resultsDir)) {
    echo "❌ Error: Results directory not found: $resultsDir\n";
    echo "Please run test_all_openapi_endpoints.php first.\n";
    exit(1);
}

echo "========================================\n";
echo "OpenAPI Test Results Analysis\n";
echo "========================================\n";
echo "Analyzing files in: $resultsDir\n\n";

// Load all test result files
$files = glob($resultsDir . '/*.json');
$testResults = [];

foreach ($files as $file) {
    $filename = basename($file);
    if ($filename === '_summary.json' || $filename === '_analysis_report.json') {
        continue;
    }

    $data = json_decode(file_get_contents($file), true);
    if ($data) {
        $testResults[$data['test_name']] = $data;
    }
}

echo "Found " . count($testResults) . " test result files\n\n";

// Analyze data structures
$analysis = [
    'generated_at' => date('Y-m-d H:i:s'),
    'total_tests' => count($testResults),
    'endpoints' => [],
    'field_mapping' => [],
    'pagination_info' => [],
    'common_fields' => [],
    'endpoint_capabilities' => [],
];

/**
 * Extract field structure from nested array
 */
function extractFields(array $data, string $prefix = ''): array
{
    $fields = [];

    foreach ($data as $key => $value) {
        $fullKey = $prefix ? "$prefix.$key" : $key;

        if (is_array($value) && !empty($value)) {
            // Check if it's an associative array or list
            if (array_keys($value) === range(0, count($value) - 1)) {
                // It's a list - analyze first item
                $fields[$fullKey] = ['type' => 'array', 'sample_count' => count($value)];
                if (!empty($value[0]) && is_array($value[0])) {
                    $fields = array_merge($fields, extractFields($value[0], "$fullKey[]"));
                } else {
                    $fields[$fullKey]['item_type'] = gettype($value[0]);
                }
            } else {
                // It's an object
                $fields[$fullKey] = ['type' => 'object'];
                $fields = array_merge($fields, extractFields($value, $fullKey));
            }
        } else {
            $fields[$fullKey] = [
                'type' => gettype($value),
                'sample' => is_string($value) ? substr($value, 0, 100) : $value,
            ];
        }
    }

    return $fields;
}

/**
 * Analyze endpoint structure
 */
function analyzeEndpoint(array $testData): array
{
    $result = $testData['result'] ?? [];
    $responseData = $result['response_data'] ?? [];

    $endpointAnalysis = [
        'success' => $result['success'] ?? false,
        'http_code' => $result['http_code'] ?? null,
        'response_time_ms' => $result['response_time_ms'] ?? null,
        'is_collection' => isset($responseData['items']),
        'is_single_item' => isset($responseData['uuid']) && !isset($responseData['items']),
        'has_pagination' => isset($responseData['pageInformation']),
        'total_count' => $responseData['count'] ?? null,
        'items_returned' => isset($responseData['items']) ? count($responseData['items']) : null,
    ];

    // Extract field structure
    if (!empty($responseData)) {
        if (isset($responseData['items']) && !empty($responseData['items'])) {
            // Collection - analyze first item
            $endpointAnalysis['fields'] = extractFields($responseData['items'][0]);
            $endpointAnalysis['collection_fields'] = extractFields([
                'count' => $responseData['count'] ?? null,
                'pageInformation' => $responseData['pageInformation'] ?? null,
            ]);
        } elseif (isset($responseData['uuid'])) {
            // Single item
            $endpointAnalysis['fields'] = extractFields($responseData);
        }
    }

    // Pagination details
    if (isset($responseData['pageInformation'])) {
        $endpointAnalysis['pagination'] = $responseData['pageInformation'];
    }

    return $endpointAnalysis;
}

// Analyze each endpoint
foreach ($testResults as $testName => $testData) {
    echo "Analyzing: $testName\n";

    $endpointAnalysis = analyzeEndpoint($testData);
    $analysis['endpoints'][$testName] = $endpointAnalysis;

    // Collect common fields across endpoints
    if (isset($endpointAnalysis['fields'])) {
        foreach ($endpointAnalysis['fields'] as $field => $info) {
            if (!isset($analysis['common_fields'][$field])) {
                $analysis['common_fields'][$field] = [
                    'occurrences' => 0,
                    'endpoints' => [],
                    'type' => $info['type'],
                ];
            }
            $analysis['common_fields'][$field]['occurrences']++;
            $analysis['common_fields'][$field]['endpoints'][] = $testName;
        }
    }
}

// Identify endpoint capabilities
$endpointTypes = [
    'research-outputs' => [],
    'persons' => [],
    'projects' => [],
    'organizational-units' => [],
    'data-sets' => [],
    'equipments' => [],
];

foreach ($testResults as $testName => $testData) {
    $endpoint = $testData['endpoint'] ?? '';
    $queryParams = $testData['query_params'] ?? [];

    foreach ($endpointTypes as $type => $capabilities) {
        if (strpos($endpoint, $type) !== false) {
            if (empty($queryParams)) {
                $endpointTypes[$type]['list'] = $testData['result']['success'] ?? false;
            } elseif (isset($queryParams['q'])) {
                $endpointTypes[$type]['search'] = $testData['result']['success'] ?? false;
            } elseif (isset($queryParams['order'])) {
                $endpointTypes[$type]['sorting'] = $testData['result']['success'] ?? false;
            } elseif (isset($queryParams['locale'])) {
                $endpointTypes[$type]['locale'] = $testData['result']['success'] ?? false;
            }

            if (strpos($endpoint, '/') > strrpos($endpoint, $type)) {
                $endpointTypes[$type]['single'] = $testData['result']['success'] ?? false;
            }
        }
    }
}

$analysis['endpoint_capabilities'] = $endpointTypes;

// Sort common fields by occurrence
uasort($analysis['common_fields'], function ($a, $b) {
    return $b['occurrences'] <=> $a['occurrences'];
});

// Save analysis
file_put_contents(
    $analysisFile,
    json_encode($analysis, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)
);

echo "\n";
echo "========================================\n";
echo "Analysis Summary\n";
echo "========================================\n";
echo "Total Endpoints Analyzed: " . count($analysis['endpoints']) . "\n";
echo "Unique Fields Found: " . count($analysis['common_fields']) . "\n";
echo "\n";

// Display endpoint capabilities
echo "Endpoint Capabilities:\n";
echo str_repeat("-", 70) . "\n";
foreach ($endpointTypes as $type => $capabilities) {
    $capList = [];
    foreach ($capabilities as $cap => $supported) {
        $capList[] = $supported ? "✅ $cap" : "❌ $cap";
    }
    echo "$type: " . implode(', ', $capList) . "\n";
}

echo "\n";
echo "Top 10 Common Fields:\n";
echo str_repeat("-", 70) . "\n";
$topFields = array_slice($analysis['common_fields'], 0, 10, true);
foreach ($topFields as $field => $info) {
    echo sprintf("%-40s %2d endpoints (%s)\n", $field, $info['occurrences'], $info['type']);
}

echo "\n";
echo "✅ Analysis saved to: _analysis_report.json\n";
echo "========================================\n";

// Create human-readable report
$reportFile = $resultsDir . '/_analysis_report.md';
$report = "# OpenAPI Test Results Analysis\n\n";
$report .= "**Generated:** " . date('Y-m-d H:i:s') . "\n\n";
$report .= "---\n\n";

$report .= "## Endpoint Capabilities\n\n";
$report .= "| Endpoint | List | Search | Single | Sorting | Locale |\n";
$report .= "|----------|------|--------|--------|---------|--------|\n";
foreach ($endpointTypes as $type => $capabilities) {
    $report .= "| `$type` |";
    foreach (['list', 'search', 'single', 'sorting', 'locale'] as $cap) {
        $status = isset($capabilities[$cap]) && $capabilities[$cap] ? '✅' : '❌';
        $report .= " $status |";
    }
    $report .= "\n";
}

$report .= "\n## Common Fields Across Endpoints\n\n";
$report .= "Fields that appear in multiple endpoints:\n\n";
$report .= "| Field | Occurrences | Type |\n";
$report .= "|-------|-------------|------|\n";
foreach (array_slice($analysis['common_fields'], 0, 20, true) as $field => $info) {
    $report .= "| `$field` | {$info['occurrences']} | {$info['type']} |\n";
}

$report .= "\n## Endpoint Details\n\n";
foreach ($analysis['endpoints'] as $testName => $endpoint) {
    $report .= "### $testName\n\n";
    $report .= "- **Success:** " . ($endpoint['success'] ? '✅ Yes' : '❌ No') . "\n";
    $report .= "- **HTTP Code:** {$endpoint['http_code']}\n";
    $report .= "- **Response Time:** {$endpoint['response_time_ms']}ms\n";
    $report .= "- **Type:** " . ($endpoint['is_collection'] ? 'Collection' : ($endpoint['is_single_item'] ? 'Single Item' : 'Unknown')) . "\n";

    if (isset($endpoint['total_count'])) {
        $report .= "- **Total Count:** {$endpoint['total_count']}\n";
    }

    if (isset($endpoint['items_returned'])) {
        $report .= "- **Items Returned:** {$endpoint['items_returned']}\n";
    }

    if (isset($endpoint['pagination'])) {
        $page = $endpoint['pagination'];
        $report .= "- **Pagination:** offset={$page['offset']}, size={$page['size']}\n";
    }

    $report .= "\n";
}

file_put_contents($reportFile, $report);

echo "📄 Markdown report saved to: _analysis_report.md\n";
echo "========================================\n";
